using System;
using System.Reflection;
using System.Threading;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Tests;

[AttributeUsage(AttributeTargets.Method, AllowMultiple = false)]
public sealed class TimedTestMethodAttribute : Attribute, ITestMethodDecorator
{
    private readonly int _warningThresholdMs;

    public TimedTestMethodAttribute(int warningThresholdMs = 5000)
    {
        _warningThresholdMs = warningThresholdMs;
    }

    public int Order => 0;

    public bool ShouldDecorate(MethodInfo methodInfo) => true;

    public TestResult[] Execute(ITestMethod testMethod, Func<ITestMethod, TestResult[]> next)
    {
        var sw = System.Diagnostics.Stopwatch.StartNew();
        var results = next(testMethod);
        sw.Stop();

        if (sw.ElapsedMilliseconds > _warningThresholdMs)
        {
            Console.WriteLine($"WARNING: {testMethod.TestMethodName} took {sw.ElapsedMilliseconds}ms (threshold: {_warningThresholdMs}ms)");
        }

        return results;
    }
}

